 model.snapshot.bodies={body(1,makeBox(Frame3(),12,8,6)),body(2,makeBox(Frame3(Vec3(40,0,0),Vec3(0,0,1),Vec3(1,0,0)),8,8,6))};model.choices={{1,"Blocco"},{2,"Altro corpo"}};
